import{_ as t,o as a,c as o,ah as r}from"./chunks/framework.DDXs_i7t.js";const p=JSON.parse('{"title":"Press Kit: The Horten Mystery","description":"","frontmatter":{},"headers":[],"relativePath":"en/pressemappe.md","filePath":"en/pressemappe.md"}'),i={name:"en/pressemappe.md"};function s(n,e,h,l,u,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="press-kit-the-horten-mystery" tabindex="-1">Press Kit: The Horten Mystery <a class="header-anchor" href="#press-kit-the-horten-mystery" aria-label="Permalink to &quot;Press Kit: The Horten Mystery&quot;">​</a></h1><p>Welcome to the official press area of the Horten Mystery. Here, journalists, bloggers, and forensics experts will find all the necessary information about the mockumentary of the year.</p><h2 id="about-the-project" tabindex="-1">About the Project <a class="header-anchor" href="#about-the-project" aria-label="Permalink to &quot;About the Project&quot;">​</a></h2><p>&quot;The Horten Mystery&quot; is a four-part mockumentary that highlights the rise and entanglements of the Horten empire with Austrian politics (especially the ÖVP). We use Gemini CLI for the forensic processing of data, chats, and historical documents.</p><h2 id="key-themes" tabindex="-1">Key Themes <a class="header-anchor" href="#key-themes" aria-label="Permalink to &quot;Key Themes&quot;">​</a></h2><ul><li><strong>The Pointillism of Money:</strong> How small donations result in a large picture of power.</li><li><strong>Hard Prose:</strong> Analysis of political interventions and patronage.</li><li><strong>Case Study Peršmanhof:</strong> The documentation of &quot;structural anti-Slovenianism&quot; and state arbitrariness as a historical echo.</li><li><strong>Market Consolidation:</strong> The transition from the Wöginger era to the Hattmannsdorfer era.</li></ul><h2 id="current-research-focus" tabindex="-1">Current Research Focus <a class="header-anchor" href="#current-research-focus" aria-label="Permalink to &quot;Current Research Focus&quot;">​</a></h2><h3 id="the-hydra-at-persmanhof" tabindex="-1">The Hydra at Peršmanhof <a class="header-anchor" href="#the-hydra-at-persmanhof" aria-label="Permalink to &quot;The Hydra at Peršmanhof&quot;">​</a></h3><p>In collaboration with those affected and legal experts, &quot;The Horten Mystery&quot; documents the unlawful criminalization of commemorative culture.</p><ul><li><strong>The Finding:</strong> The Carinthian Administrative Court confirmed on April 16, 2026, the unlawfulness of massive police operations at the Peršmanhof memorial site.</li><li><strong>Structural Anti-Slovenianism:</strong> We shed light on the continuity of repression against the Slovenian ethnic group – from the SS massacres in 1945 to today&#39;s bureaucratic and police harassment under the guise of nature conservation laws.</li><li><strong>Systemic Contrast:</strong> While interventions in the tax office (Wöginger case) are downplayed as &quot;citizen proximity,&quot; civil society commemoration is met with helicopters and state security operations.</li></ul><h2 id="press-contact-materials" tabindex="-1">Press Contact &amp; Materials <a class="header-anchor" href="#press-contact-materials" aria-label="Permalink to &quot;Press Contact &amp; Materials&quot;">​</a></h2><p>For interview requests, high-resolution imagery, or exclusive insights into forensic data, please contact the project management via the <a href="/en/mitmachen.html">Whistleblower Tip-Line</a>.</p><hr><h2 id="exclusive-guest-contribution-the-headbutt-kopfnuss-on-the-woginger-resignation" tabindex="-1">Exclusive Guest Contribution: The &quot;Headbutt&quot; (Kopfnuss) on the Wöginger Resignation <a class="header-anchor" href="#exclusive-guest-contribution-the-headbutt-kopfnuss-on-the-woginger-resignation" aria-label="Permalink to &quot;Exclusive Guest Contribution: The &quot;Headbutt&quot; (Kopfnuss) on the Wöginger Resignation&quot;">​</a></h2><p><em>By our guest author: Florian Armin Nusser (Investigative-Cynical Collective)</em></p><h3 id="headbutt-2303-the-hard-prose-of-disappearing" tabindex="-1">Headbutt #2303: The Hard Prose of Disappearing <a class="header-anchor" href="#headbutt-2303-the-hard-prose-of-disappearing" aria-label="Permalink to &quot;Headbutt #2303: The Hard Prose of Disappearing&quot;">​</a></h3><p>Good evening, dear Austria. Or as they say in the ÖVP headquarters: &quot;Good night, decency.&quot;</p><p>We need to talk. About Gustl. Our August Wöginger. The man who taught us &quot;Hard Prose&quot; has invented a new literary genre today: The <strong>&quot;Fiction of Work Overload&quot;</strong>.</p><p>Here are the facts, briefly classified:</p><ol><li><p><strong>The Miracle of Linz:</strong> August Wöginger resigns as deputy state party leader in Upper Austria. The reason? He is &quot;more than overloaded.&quot; Right now. The fact that the verdict in the trial for incitement to abuse of office at the Linz Regional Court is due on <strong>April 21</strong>, followed only 72 hours later by the state party congress, is, of course, a complete coincidence. Just as it is a complete coincidence that you always have to go to the toilet when the bill arrives while playing Eurozero.</p></li><li><p><strong>The Hattmannsdorfer File:</strong> While Gustl is cultivating his &quot;overload,&quot; Wolfgang Hattmannsdorfer is moving up. The &quot;political professional.&quot; A man who thinks so strategically that he has probably already planned his own canonization, including sponsorship by the Chamber of Commerce (WKO). He is the new, smooth face. Without the aroma of the defendant&#39;s dock. For now.</p></li><li><p><strong>The Hard Prose of Reality:</strong> When the ÖVP speaks of &quot;voluntary withdrawal,&quot; it is usually the polite paraphrase for &quot;We have already fueled the getaway vehicle.&quot; Wöginger retains his federal functions. Because in the ÖVP, a trial for abuse of office is not a reason for resignation, but a kind of extra-occupational training.</p></li></ol><p><strong>Conclusion:</strong> Mr. Wöginger, you say you are overloaded? So are we. Specifically with your excuses.</p><p>Good night. And look at it closely. It is a picture made of many small dots. If you move far enough away, it looks like a resignation. If you look closely, it&#39;s just fear of the judge.</p><hr><p style="font-size:0.8rem;color:#888;text-align:center;"> This is a satirical art project. <a href="disclaimer">Satire Disclaimer</a></p>',24)])])}const f=t(i,[["render",s]]);export{p as __pageData,f as default};
